namespace AvaloniaCharts.Controls;

/// <summary>
/// Стиль линии для 2D графика.
/// </summary>
public enum LineStyle
{
    /// <summary>
    /// Сплошная линия.
    /// </summary>
    Solid,

    /// <summary>
    /// Штриховая (прерывистая) линия.
    /// </summary>
    Dashed,

    /// <summary>
    /// Пунктирная линия из точек.
    /// </summary>
    Dotted
}
